// src/components/Navbar.jsx
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const badgeStyle = (role) => ({
  padding: "4px 10px",
  borderRadius: "999px",
  fontSize: "12px",
  fontWeight: 600,
  background:
    role === "admin"
      ? "#ef4444"
      : role === "advisor"
      ? "#3b82f6"
      : "#22c55e",
  color: "#fff",
  marginLeft: 8,
});

const Navbar = () => {
  const { isAuthenticated, user, role, logout } = useAuth();

  return (
    <nav
      style={{
        display: "flex",
        alignItems: "center",
        gap: 16,
        padding: "16px 24px",
        background: "#020617",
      }}
    >
      <Link to="/" style={{ fontWeight: 700 }}>
        ThesisCheck
      </Link>

      {isAuthenticated && (
        <>
          <Link to="/dashboard">Dashboard</Link>

          {role === "student" && <Link to="/upload">Upload</Link>}
          {role === "admin" && <Link to="/admin">Admin</Link>}

          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center" }}>
            <span>{user.email}</span>
            <span style={badgeStyle(role)}>{role}</span>

            <button
              onClick={logout}
              style={{
                marginLeft: 16,
                padding: "6px 12px",
                borderRadius: 8,
                border: "none",
                cursor: "pointer",
              }}
            >
              Logout
            </button>
          </div>
        </>
      )}

      {!isAuthenticated && <Link to="/login">Login</Link>}
    </nav>
  );
};

export default Navbar;
